contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmt, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmt);

        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeCBal = address(c).balance;
        require(beforeBal >= am);

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterCBal = address(c).balance;

        assert(reverted || (afterBal == beforeBal - am && afterCBal == beforeCBal - am));
    }

    receive() external payable {}
}

